package io.nebulaflow.api;
import io.nebulaflow.api.ApiModels.*; import io.nebulaflow.service.WorkflowService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1") public class WorkflowController {private final WorkflowService service; public WorkflowController(WorkflowService s){service=s;} @PostMapping("/workflows") public ResponseEntity<WorkflowResponse> create(@Valid @RequestBody CreateWorkflowRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));} @GetMapping("/workflows") public List<WorkflowSummary> list(){return service.list();} @PostMapping("/workflows/{id}/runs") public ResponseEntity<RunResponse> run(@PathVariable UUID id,@RequestBody(required=false) StartRunRequest r){return ResponseEntity.accepted().body(service.start(id,r));} @GetMapping("/runs/{id}") public RunResponse get(@PathVariable UUID id){return service.getRun(id);}}
